1	"use client";
2	
3	import { useState } from "react";
4	import { useAuth } from "@/hooks/useAuth";
5	import { useTeam } from "@/hooks/useTeam";
6	import { supabase } from "@/integrations/supabase/client";
7	import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
8	import { Button } from "@/components/ui/button";
9	import { Input } from "@/components/ui/input";
10	import { Label } from "@/components/ui/label";
11	import { Switch } from "@/components/ui/switch";
12	import { LogOut, Zap, MessageCircle } from "lucide-react";
13	import { toast } from "sonner";
14	import AvailabilitySettings from "@/components/AvailabilitySettings";
15	
16	
17	const Settings = () => {
18	  const { user, profile, signOut, refreshProfile } = useAuth();
19	  const { team } = useTeam();
20	  const autoRank = profile?.auto_rank_enabled ?? true;
21	  const [whatsappNumber, setWhatsappNumber] = useState<string>((profile as any)?.whatsapp_number ?? "");
22	  const [savingWhatsapp, setSavingWhatsapp] = useState(false);
23	
24	  const toggleAutoRank = async (enabled: boolean) => {
25	    if (!user) return;
26	    try {
27	      const { error } = await supabase.from("profiles")
28	        .update({ auto_rank_enabled: enabled } as never)
29	        .eq("user_id", user.id);
30	      if (error) throw error;
31	      await refreshProfile();
32	      toast.success(enabled ? "Auto-rank enabled" : "Auto-rank disabled");
33	    } catch {
34	      toast.error("Failed to update setting");
35	    }
36	  };
37	
38	  const saveWhatsappNumber = async () => {
39	    if (!user) return;
40	    setSavingWhatsapp(true);
41	    try {
42	      const { error } = await supabase.from("profiles")
43	        .update({ whatsapp_number: whatsappNumber.trim() || null } as never)
44	        .eq("user_id", user.id);
45	      if (error) throw error;
46	      await refreshProfile();
47	      toast.success("WhatsApp number saved");
48	    } catch {
49	      toast.error("Failed to save WhatsApp number");
50	    } finally {
51	      setSavingWhatsapp(false);
52	    }
53	  };
54	
55	  return (
56	    <main className="w-full px-6 sm:px-8 lg:px-10 py-8">
57	        <h1 className="text-2xl font-bold text-foreground mb-6">Settings</h1>
58	        <div className="space-y-6">
59	          {/* Auto-rank toggle */}
60	          <Card className="border border-border/60 shadow-sm">
61	            <CardHeader className="pb-3">
62	              <div className="flex items-center justify-between">
63	                <div className="flex items-center gap-2">
64	                  <Zap className="h-5 w-5 text-primary" />
65	                  <CardTitle className="text-sm font-semibold">Auto-rank resumes</CardTitle>
66	                </div>
67	                <Switch checked={autoRank} onCheckedChange={toggleAutoRank} />
68	              </div>
69	              <CardDescription>
70	                {autoRank
71	                  ? "Resumes are automatically scored after upload. Credits are used immediately."
72	                  : "Resumes stay as Pending after upload. You choose when to rank and spend credits."}
73	              </CardDescription>
74	            </CardHeader>
75	          </Card>
76	
77	          {/* WhatsApp number */}
78	          <Card className="border border-border/60 shadow-sm">
79	            <CardHeader className="pb-3">
80	              <div className="flex items-center gap-2">
81	                <MessageCircle className="h-5 w-5 text-[#25D366]" />
82	                <CardTitle className="text-sm font-semibold">WhatsApp Number</CardTitle>
83	              </div>
84	              <CardDescription>
85	                Your WhatsApp number is pre-filled when messaging candidates. Include country code (e.g. +1 555 123 4567).
86	              </CardDescription>
87	            </CardHeader>
88	            <CardContent>
89	              <div className="flex items-center gap-2">
90	                <div className="flex-1">
91	                  <Label htmlFor="whatsapp-number" className="sr-only">WhatsApp Number</Label>
92	                  <Input
93	                    id="whatsapp-number"
94	                    value={whatsappNumber}
95	                    onChange={(e) => setWhatsappNumber(e.target.value)}
96	                    placeholder="+1 555 123 4567"
97	                    type="tel"
98	                  />
99	                </div>
100	                <Button
101	                  size="sm"
102	                  onClick={saveWhatsappNumber}
103	                  disabled={savingWhatsapp}
104	                  className="shrink-0"
105	                >
106	                  {savingWhatsapp ? "Saving..." : "Save"}
107	                </Button>
108	              </div>
109	            </CardContent>
110	          </Card>
111	
112	          {user && (
113	            <AvailabilitySettings userId={user.id} teamId={team?.id} />
114	          )}
115	
116	
117	          <Card className="border border-border/60 shadow-sm">
118	            <CardHeader>
119	              <CardTitle className="flex items-center gap-2 text-sm font-semibold">
120	                <LogOut className="h-5 w-5" />
121	                Account
122	              </CardTitle>
123	            </CardHeader>
124	            <CardContent>
125	              <Button variant="outline" onClick={signOut}>
126	                Sign out
127	              </Button>
128	            </CardContent>
129	          </Card>
130	        </div>
131	      </main>
132	  );
133	};
134	
135	export default Settings;
