140	// ── Main page ────────────────────────────────────────────────────────────────
141	
142	const Billing = () => {
143	  const { user, profile, refreshProfile } = useAuth();
144	
145	  const [annualToggle, setAnnualToggle] = useState(false);
146	  const [buying, setBuying] = useState<string | null>(null);
147	  const [cancelling, setCancelling] = useState(false);
148	  const [downgrading, setDowngrading] = useState(false);
149	  const [confirmAction, setConfirmAction] = useState<{
150	    type: "upgrade" | "downgrade" | "cancel_subscription";
151	    planId?: string;
152	    planName?: string;
153	    price?: number;
154	  } | null>(null);
155	
156	  const currentPlan = profile?.plan ?? "free";
157	  const isPaid = currentPlan !== "free";
158	  const subscriptionEndsAt = (profile as any)?.subscription_ends_at
159	    ? new Date((profile as any).subscription_ends_at)
160	    : null;
161	  const isExpired = subscriptionEndsAt ? subscriptionEndsAt < new Date() : false;
162	  const hasActiveSubscription = !!(profile as any)?.dodo_subscription_id;
163	
164	  // Credits
165	  const subCredits = profile?.subscription_credits ?? 0;
166	  const bonusCredits = profile?.bonus_credits ?? 0;
167	  const legacyCredits = profile?.credits ?? 0;
168	  const splitTotal = subCredits + bonusCredits;
169	  const totalCredits = splitTotal > 0 ? splitTotal : legacyCredits;
170	
171	  const { data: plans } = useQuery({
172	    queryKey: ["subscription_plans_active"],
173	    queryFn: async () => {
174	      const { data, error } = await supabase.from("plans")
175	        .select("*")
176	        .eq("active" as never, true)
177	        .order("price" as never);
178	      if (error) throw error;
179	      return data;
180	    },
181	  });
182	
183	  // Filter by billing type when toggle changes
184	  const billingType = annualToggle ? "yearly" : "monthly";
185	  const allBillingTypes = plans?.map((p: any) => p.billing_type) ?? [];
186	  const hasAnnual = allBillingTypes.includes("yearly");
187	  const filteredPlans = hasAnnual
188	    ? plans?.filter((p: any) => p.billing_type === billingType)
189	    : plans;
190	
191	  const popularIdx =
192	    filteredPlans && filteredPlans.length > 1
193	      ? Math.floor((filteredPlans.length - 1) / 2)
194	      : -1;
195	
196	  const handleSubscribe = async (planId: string) => {
197	    if (!user) return;
198	    setBuying(planId);
199	    try {
200	      const { data, error } = await supabase.functions.invoke("create-dodo-checkout", {
201	        body: {
202	          plan_id: planId,
203	          return_url: `${window.location.origin}/payment/callback`,
204	        },
205	      });
206	      if (error) throw error;
207	      if (!data?.checkout_url) {
208	        toast.error(data?.error || "Failed to create checkout session");
209	        return;
210	      }
211	      window.location.href = data.checkout_url;
212	    } catch (err: unknown) {
213	      toast.error(err instanceof Error ? err.message : "Checkout failed");
214	    } finally {
215	      setBuying(null);
216	    }
217	  };
218	
219	  const handleCancelSubscription = async () => {
220	    setCancelling(true);
221	    try {
222	      const { error } = await supabase.functions.invoke("cancel-dodo-subscription", {});
223	      if (error) throw error;
224	      toast.success("Auto-renewal cancelled. Your plan stays active until the billing period ends.");
225	      await refreshProfile();
226	      setConfirmAction(null);
227	    } catch (err: unknown) {
228	      toast.error("Failed to cancel: " + (err instanceof Error ? err.message : "Unknown error"));
229	    } finally {
230	      setCancelling(false);
231	    }
232	  };
233	
234	  const handleDowngradeToFree = async () => {
235	    setDowngrading(true);
236	    try {
237	      if (hasActiveSubscription) {
238	        const { data, error: cancelError } = await supabase.functions.invoke(
239	          "cancel-dodo-subscription",
240	          {}
241	        );
242	        if (cancelError || data?.error) {
243	          toast.error(
244	            "Could not cancel subscription with payment provider. Please try again or contact support."
245	          );
246	          setDowngrading(false);
247	          return;
248	        }
249	      }
250	      const { error } = await supabase.from("profiles")
251	        .update({
252	          plan: "free",
253	          subscription_ends_at: null,
254	          dodo_subscription_id: null,
255	        } as never)
256	        .eq("user_id", user?.id);
257	      if (error) throw error;
258	      toast.success("Switched to Free plan. Your remaining credits are preserved.");
259	      await refreshProfile();
260	      setConfirmAction(null);
261	    } catch (err: unknown) {
262	      toast.error(
263	        "Failed to downgrade: " + (err instanceof Error ? err.message : "Unknown error")
264	      );
265	    } finally {
266	      setDowngrading(false);
267	    }
268	  };
269	
270	  const handleConfirmedAction = () => {
271	    if (!confirmAction) return;
272	    if (confirmAction.type === "upgrade" && confirmAction.planId) {
273	      handleSubscribe(confirmAction.planId);
274	      setConfirmAction(null);
275	    } else if (confirmAction.type === "downgrade") {
276	      handleDowngradeToFree();
277	    } else if (confirmAction.type === "cancel_subscription") {
278	      handleCancelSubscription();
279	    }
280	  };
281	
282	  return (
283	    <>
284	    <main className="w-full px-6 sm:px-8 lg:px-10 py-8">
285	      {/* Page header */}
286	        <div className="mb-8">
287	          <h1 className="text-2xl font-semibold text-foreground tracking-tight">Billing & Plan</h1>
288	          <p className="text-sm text-muted-foreground mt-1">
289	            Manage your subscription and view usage history.
290	          </p>
291	        </div>
292	
293	        <div className="space-y-8">
294	          {/* ── Current plan summary card ─────────────────────────────── */}
295	          <Card>
296	            <div className="px-6 pt-5 pb-5 flex items-start justify-between gap-4 flex-wrap">
297	              <div className="flex items-center gap-3">
298	                <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-primary/10 shrink-0">
299	                  {isPaid ? (
300	                    <Crown className="h-5 w-5 text-primary" />
301	                  ) : (
302	                    <Zap className="h-5 w-5 text-muted-foreground" />
303	                  )}
304	                </div>
305	                <div>
306	                  <div className="flex items-center gap-2 flex-wrap">
307	                    <Badge
308	                      variant={isPaid ? "default" : "secondary"}
309	                      className="gap-1.5 capitalize text-sm px-2.5 py-0.5"
310	                    >
311	                      {isPaid ? <Crown className="h-3.5 w-3.5" /> : <Zap className="h-3.5 w-3.5" />}
312	                      {isPaid ? currentPlan : "Free"}
313	                    </Badge>
314	                    {subscriptionEndsAt && !isExpired && (
315	                      <Badge variant="secondary" className="gap-1 text-xs">
316	                        <CalendarClock className="h-3 w-3" />
317	                        {hasActiveSubscription
318	                          ? `Renews ${format(subscriptionEndsAt, "MMM d, yyyy")}`
319	                          : `Active until ${format(subscriptionEndsAt, "MMM d, yyyy")}`}
320	                      </Badge>
321	                    )}
322	                    {isExpired && (
323	                      <Badge variant="destructive" className="text-xs">Expired</Badge>
324	                    )}
325	                  </div>
326	                  <p className="text-sm text-muted-foreground mt-1">
327	                    {totalCredits.toLocaleString()} credits remaining
328	                    {subCredits > 0 && bonusCredits > 0 && (
329	                      <span className="text-xs ml-1">
330	                        ({subCredits.toLocaleString()} monthly + {bonusCredits.toLocaleString()} bonus)
331	                      </span>
332	                    )}
333	                  </p>
334	                </div>
335	              </div>
336	
337	              <div className="flex items-center gap-2 shrink-0">
338	                {isPaid && hasActiveSubscription && !isExpired && (
339	                  <Button
340	                    variant="outline"
341	                    size="sm"
342	                    className="h-8 text-xs gap-1.5 border-destructive/30 text-destructive hover:bg-destructive/10 hover:text-destructive"
343	                    onClick={() => setConfirmAction({ type: "cancel_subscription" })}
344	                    disabled={cancelling}
345	                  >
346	                    {cancelling ? (
347	                      <Loader2 className="h-3 w-3 animate-spin" />
348	                    ) : (
349	                      <XCircle className="h-3 w-3" />
350	                    )}
351	                    Cancel renewal
352	                  </Button>
353	                )}
