131	      // Graceful fallback: if table doesn't exist or RLS blocks, return empty
132	      if (poolError) {
133	        const code = (poolError as any)?.code;
134	        // 42P01 = table doesn't exist, PGRST116 = no rows, 42501 = permission denied
135	        if (code === "42P01" || code === "PGRST116" || code === "42501") return [];
136	        throw poolError;
