151	      (resumesRes.data ?? []).forEach((r: any) => { resumeMap[r.id] = r; });
152	      const jobMap: Record<string, any> = {};
153	      (jobsRes.data ?? []).forEach((j: any) => { jobMap[j.id] = j; });
