CREATE TABLE IF NOT EXISTS talent_pool (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id uuid NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  resume_id uuid REFERENCES rankora_resumes(id) ON DELETE SET NULL,
  candidate_name text,
  candidate_email text,
  tags text[],
  notes text,
  source text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE talent_pool ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS talent_pool_all ON talent_pool;
CREATE POLICY talent_pool_all ON talent_pool FOR ALL TO authenticated USING (is_account_member(account_id)) WITH CHECK (is_account_member(account_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON talent_pool TO authenticated;

-- sequences (email/outreach sequences)
CREATE TABLE IF NOT EXISTS sequences (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id uuid NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  name text NOT NULL,
  description text,
  status text NOT NULL DEFAULT 'draft',
  created_by uuid REFERENCES users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE sequences ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS sequences_all ON sequences;
CREATE POLICY sequences_all ON sequences FOR ALL TO authenticated USING (is_account_member(account_id)) WITH CHECK (is_account_member(account_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON sequences TO authenticated;

